class DirView(private val raw: Dir, private val m: Membrane) : Dir by raw {
    override fun open(path: String): File {          // the mediated member
        check(!m.revoked) { "revoked" }
        return m.wrap(raw.open(path))                // wrap the way out
    }
    // every other member of Dir still forwards to raw, unmediated
}

