val view = Proxy.newProxyInstance(
    Dir::class.java.classLoader, arrayOf(Dir::class.java)
) { _, method, args ->
    if (m.revoked) throw IllegalStateException("revoked")
    val wrapped = args?.map { if (it is Dir) m.wrap(it) else it }?.toTypedArray()  // wrap in
    m.wrap(method.invoke(raw, *(wrapped ?: emptyArray())))                       // wrap out
} as Dir
